import { redirect } from 'next/navigation'

type ContactFormProps = {
  contactStatus?: string | string[]
}

export default function ContactForm({ contactStatus }: ContactFormProps) {
  async function submitContactMessage(formData: FormData) {
    'use server'

    const name = String(formData.get('name') ?? '').trim()
    const email = String(formData.get('email') ?? '').trim()
    const message = String(formData.get('message') ?? '').trim()

    if (!name || !email || !message) {
      redirect('/?contact=invalid')
    }

    console.log('Contact message:', { name, email, message })
    redirect('/?contact=sent')
  }

  const status = Array.isArray(contactStatus)
    ? contactStatus[0]
    : contactStatus

  return (
    <div>
      <h2>Contact Us</h2>
      {status === 'invalid' && (
        <p role="alert">Please provide your name, email, and message.</p>
      )}
      {status === 'sent' && (
        <p role="status">Thanks — we received your message.</p>
      )}
      <form action={submitContactMessage}>
        <div>
          <label htmlFor="contact-name">Name</label>
          <input
            id="contact-name"
            name="name"
            type="text"
            autoComplete="name"
            aria-required="true"
          />
        </div>
        <div>
          <label htmlFor="contact-email">Email</label>
          <input
            id="contact-email"
            name="email"
            type="email"
            autoComplete="email"
            aria-required="true"
          />
        </div>
        <div>
          <label htmlFor="contact-message">Message</label>
          <textarea
            id="contact-message"
            name="message"
            rows={5}
            aria-required="true"
          />
        </div>
        <button type="submit">Send message</button>
      </form>
    </div>
  )
}

